contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Fallback to receive ether
    fallback() external payable {}
    receive() external payable {}

    function test(address _owner, address _recipient) public {
        require(_owner != address(0));
        require(_recipient != address(0));
        require(_owner != _recipient);
        // Fund the contract and record balance
        uint bal = address(c).balance;
        // Attempt withdrawal as owner
        // We simulate a non-owner call? No, we need the deciding call.
        // The rule is about owner's ability to drain.
        // We need to call withdrawAll, and we must be the owner.
        // But we can't change msg.sender. The test must be designed such that
        // the verifier assumes arbitrary msg.sender. We use parameters.
        // We'll assert the property after calling withdrawAll from an arbitrary caller.
        bool success;
        uint preBal = address(c).balance;
        (success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));
        uint postBal = address(c).balance;
        // Rule: if call succeeded and sender is owner, balance must be 0.
        // But we cannot directly check msg.sender. We use a trick: we need owner in constructor.
        // Actually, the constructor of C sets owner. We can pass that owner as parameter.
        // In M, send might fail and balance might not be 0.
        // We can assert: after owner calls withdrawAll, the contract balance is 0.
        // But we cannot ensure msg.sender == owner in our test because we don't control it.
        // So we test the general property: for any sender, if the call succeeds and the sender is owner, balance must be zero.
        // Since verifier explores all states, it will find a violating case in M (owner calls, send fails, balance unchanged).
        // But we need a single assert. We can assert that (success && (preBal > 0) implies (postBal == 0)).
        // However, in P, transfer reverts on failure, so if success, balance is always 0. In M, send can succeed but not transfer funds.
        assert(!success || !(preBal > 0) || postBal == 0);
    }
}

