pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(amount > 0);
        // Deploy a helper that explicitly rejects incoming Ether
        NonAcceptor nonAcceptor = new NonAcceptor();
        address payable target = payable(address(nonAcceptor));
        // Fund the contract
        vm.deal(address(c), amount);
        // Owner withdraws to a non-accepting target
        vm.prank(address(this));
        c.withdrawAll(target);
        // After the call, the contract balance must be zero.
        // With transfer (C) it would have reverted, but we are testing the send version.
        // Actually the reference uses transfer which reverts on failure, so the call above
        // would revert and the following assertion would not be reached.
        // We need to avoid revert in the reference to check the property. Let's use try/catch.
        bool revert_occurred;
        try c.withdrawAll(target) {
            revert_occurred = false;
        } catch {
            revert_occurred = true;
        }
        // The property: the balance must be zero if the call did not revert.
        // But in the reference, transfer reverts on failure, so it always reverts,
        // and we can't observe a successful call with non-zero balance.
        // So we need to adjust: call withdrawAll as a low-level call to capture success/failure,
        // and then check the balance.
        // Reset state: redeploy c with same funding.
        c = new C(address(this));
        vm.deal(address(c), amount);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", target));
        // Reference: success = false (transfer reverted), balance unchanged.
        // Buggy: success = true (send did not revert), balance unchanged.
        // Property: success implies balance == 0.
        assertTrue(!success || address(c).balance == 0);
    }
}

contract NonAcceptor {
    receive() external payable {
        revert("I do not accept Ether");
    }
}

